// Generated by zig-anything for a port unit. Safe to extend.
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    // The port itself, importable by other Zig projects as module "port".
    const port = b.addModule("port", .{
        .root_source_file = b.path("src/port.zig"),
        .target = target,
        .optimize = optimize,
    });

    const harness = b.addExecutable(.{
        .name = "harness",
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/harness.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    b.installArtifact(harness);

    const tests = b.addTest(.{ .root_module = port });
    const test_step = b.step("test", "Run the port's own unit tests");
    test_step.dependOn(&b.addRunArtifact(tests).step);
}
